def main():
    global MRCP_TOPICS, FCPS_TOPICS, NLE_TOPICS
    MRCP_TOPICS = (MRCP_TOPICS + MRCP_ADDITIONAL)[:100]
    FCPS_TOPICS = (FCPS_TOPICS + FCPS_ADDITIONAL + FCPS_EXTRA_20)[:100]
    NLE_TOPICS = (NLE_TOPICS + NLE_ADDITIONAL + NLE_EXTRA_25)[:100]

    print(f"Total MRCP topics: {len(MRCP_TOPICS)}")
    print(f"Total FCPS topics: {len(FCPS_TOPICS)}")
    print(f"Total NLE topics: {len(NLE_TOPICS)}")

    assert len(MRCP_TOPICS) == 100, f"Expected 100 MRCP topics, got {len(MRCP_TOPICS)}"
    assert len(FCPS_TOPICS) == 100, f"Expected 100 FCPS topics, got {len(FCPS_TOPICS)}"
    assert len(NLE_TOPICS) == 100, f"Expected 100 NLE topics, got {len(NLE_TOPICS)}"

    # Validate all subjects and systems
    for title, subj, sys_name, snip, g_name, g_url in MRCP_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in FCPS_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in NLE_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    out_path = os.path.join(os.path.dirname(__file__), "mega40_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 40 Topics Part B\n")
        f.write("# MRCP (100 topics) + FCPS (100 topics) + NLE (100 topics)\n\n")
        f.write(f"MRCP_TOPICS = {repr(MRCP_TOPICS)}\n\n")
        f.write(f"FCPS_TOPICS = {repr(FCPS_TOPICS)}\n\n")
        f.write(f"NLE_TOPICS = {repr(NLE_TOPICS)}\n")
    print(f"Successfully generated {out_path}!")

if __name__ == "__main__":
    main()
